def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    round_no = n + 1

    opp_d = sum(1 for _, b in history if b == 'D')

    if opp_d == 0:
        if round_no >= 14:
            return 'D'
        if round_no in (2, 5, 8, 11):
            return 'D'
        return 'C'

    recent5 = history[-5:] if n >= 5 else history
    recent_opp_d = sum(1 for _, b in recent5 if b == 'D')

    _, last_opp = history[-1]

    consec_opp_d = 0
    for _, b in reversed(history):
        if b == 'D':
            consec_opp_d += 1
        else:
            break

    recent7 = history[-7:] if n >= 7 else history
    recent_my_d7 = sum(1 for a, _ in recent7 if a == 'D')

    if n >= 95:
        if last_opp == 'D' or recent_opp_d >= 2 or opp_d * 5 >= n * 2:
            return 'D'
        return 'C'

    if n >= 6 and opp_d * 5 >= n * 2:
        return 'D'

    if opp_d * 2 > n:
        return 'D'

    if recent_opp_d >= 3 or consec_opp_d >= 2:
        return 'D'

    if last_opp == 'D':
        if recent_my_d7 == 0:
            return 'D'
        return 'C'

    if recent_opp_d >= 2 and recent_my_d7 <= 1:
        return 'D'

    return 'C'
